import pg from 'pg';
import {PostgresAgentSharedCost,SqliteAgentTokenBudget,AgentBudgetRecovery} from '../../dist/index.js';
const pool=new pg.Pool({connectionString:process.env.APP_MIXER_TEST_POSTGRES_URL,options:`-c search_path=${process.env.APP_MIXER_TEST_SCHEMA}`}),scope={tenantId:'t',agentId:'agent'},runId='recovery-crash',actor={tenantId:'t',principalId:'operator'};
const ledger=new PostgresAgentSharedCost({enabled:true,scope:{tenantId:'t',budgetId:runId,currency:'USD',maxMicros:1000},query:(sql,args)=>pool.query(sql,args),authorize:()=>true,transaction:async operation=>{const client=await pool.connect();try{await client.query('BEGIN');const value=await operation((sql,args)=>client.query(sql,args));await client.query('COMMIT');process.send('after-recovery-commit');await new Promise(()=>{});return value;}catch(error){await client.query('ROLLBACK');throw error;}finally{client.release();}}});
const budget=new SqliteAgentTokenBudget(process.env.APP_MIXER_TEST_DB,{scope,runId,leaseToken:process.env.APP_MIXER_TEST_LEASE,maxTokens:100,cost:{currency:'USD',maxMicros:1000},clock:()=>110});
try{const recovery=new AgentBudgetRecovery({budget,target:{scope,runId,maxTokens:100},sharedCost:ledger,authorize:()=>true,verify:()=>({usedTokens:10,usedCostMicros:200})});await recovery.reconcile(actor,'call','provider-evidence');throw Error('Expected worker termination');}catch(error){process.send({error:String(error)});process.exitCode=1;budget.close();await pool.end();}
